"""Build a no-install, browser-native Aura Ledger hackathon demo."""
from __future__ import annotations

import json
from pathlib import Path

from src.backtest import HISTORICAL_REGIMES, run_backtest
from src.classifier import load_model
from src.data_loader import load_price_data
from src.detection import compute_features
from src.ledger import HashChainLedger
from src.portfolio import SimulatedBroker

ROOT = Path(__file__).resolve().parent
OUTPUT = ROOT / "Aura_Ledger_Interactive_Demo.html"

