EXECUTION_PANEL = '<section class="execution-deck" id="executionDeck" aria-label="Execution controls"><div class="execution-label">EXECUTION PROTOCOL</div><div class="mode-choices" role="group" aria-label="Execution mode"><button class="mode-btn active" id="autoMode" type="button" aria-pressed="true">AUTO EXECUTION</button><button class="mode-btn" id="manualMode" type="button" aria-pressed="false">MANUAL APPROVAL</button></div><div class="execution-readout"><span class="execution-dot" id="executionDot"></span><span id="executionCopy">Auto mode will execute validated historical decisions during replay.</span></div><button class="approval-btn" id="approveBtn" type="button">APPROVE &amp; CONTINUE</button></section>'
UX_CSS += r""".ledger-panel{margin-top:10px}.ledger-title{display:flex;align-items:center;gap:9px}.chain-badge{margin-left:auto;color:#14e7d5;font:700 10px Consolas,monospace;letter-spacing:.9px}.chain-badge:before{content:'● ';}.ledger-grid{display:grid;grid-template-columns:1.05fr 1.3fr 2.4fr 1.4fr;font:10px Consolas,monospace;border:1px solid rgba(29,59,89,.75);border-radius:5px;overflow:hidden}.ledger-row{display:contents}.ledger-row>span{padding:9px 10px;border-top:1px solid rgba(29,59,89,.55);color:#c6d9ea;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.ledger-head>span{border-top:0;background:#0b1d31;color:#8fa9c5;font-size:9px;letter-spacing:.8px}.ledger-row.current>span{background:rgba(20,231,213,.07);color:#ecf7ff}.ledger-hash{color:#14e7d5!important}.ledger-empty{padding:14px;color:#8fa9c5;font:11px Consolas,monospace}@media(max-width:720px){.ledger-grid{grid-template-columns:1fr 1.5fr}.ledger-row>span:nth-child(3),.ledger-row>span:nth-child(4){display:none}.chain-badge{margin-left:0}}"""
LEDGER_PANEL = '<section class="panel ledger-panel" aria-label="Tamper-evident decision ledger"><div class="title ledger-title">TAMPER-EVIDENT DECISION LEDGER <span class="chain-badge" id="chainStatus">CHAIN VERIFIED</span></div><div class="ledger-grid" id="ledgerRows"><div class="ledger-empty">Loading decision ledger...</div></div></section>'
LEDGER_SCRIPT = r"""<script>
function renderLedger(){const root=$('ledgerRows'),status=$('chainStatus'),recent=data.slice(Math.max(0,index-4),index+1).reverse();status.textContent='CHAIN VERIFIED · '+(index+1)+' DECISIONS';const header='<div class="ledger-row ledger-head"><span>DATE</span><span>MODE</span><span>DECISION</span><span>HASH</span></div>';const rows=recent.map((r,position)=>'<div class="ledger-row '+(position===0?'current':'')+'"><span>'+r.date+'</span><span>'+r.mode.toUpperCase()+'</span><span>'+r.action+'</span><span class="ledger-hash">'+r.hash+'</span></div>').join('');root.innerHTML=header+rows}
const auraRender=render;render=function(){auraRender();renderLedger()};renderLedger();
</script>"""
MANUAL_MODE_SCRIPT = r"""<script>
let executionMode='auto',manualPlaying=false,pendingIndex=null,manualLast=0,manualCredit=0;
const isDecision=row=>row&&row.action.indexOf('SELL ')===0;
function refreshExecutionPanel(){const deck=$('executionDeck'),dot=$('executionDot'),copy=$('executionCopy'),approve=$('approveBtn');const pending=pendingIndex!==null?data[pendingIndex]:null;deck.classList.toggle('pending',Boolean(pending));dot.classList.toggle('manual',executionMode==='manual');if(pending){copy.textContent='Decision pending for '+pending.date+': '+pending.action+'. Review and approve execution.';approve.classList.add('visible');return}approve.classList.remove('visible');copy.textContent=executionMode==='manual'?'Manual mode pauses before every sell or re-entry decision.':'Auto mode executes validated historical decisions during replay.'}
function setExecutionMode(mode){executionMode=mode;manualPlaying=false;pendingIndex=null;manualCredit=0;$('autoMode').classList.toggle('active',mode==='auto');$('manualMode').classList.toggle('active',mode==='manual');$('autoMode').setAttribute('aria-pressed',String(mode==='auto'));$('manualMode').setAttribute('aria-pressed',String(mode==='manual'));$('playBtn').textContent='START REPLAY';refreshExecutionPanel()}
function stopAtDecision(next){pendingIndex=next;manualPlaying=false;manualCredit=0;$('playBtn').textContent='DECISION REQUIRED';refreshExecutionPanel()}
function advanceReplay(steps){for(let step=0;step<steps&&index<data.length-1;step++){const next=index+1;if(executionMode==='manual'&&isDecision(data[next])){stopAtDecision(next);return}index=next}render();refreshExecutionPanel();if(index===data.length-1){manualPlaying=false;$('playBtn').textContent='REPLAY COMPLETE'}}
$('autoMode').onclick=()=>setExecutionMode('auto');$('manualMode').onclick=()=>setExecutionMode('manual');$('playBtn').onclick=()=>{if(pendingIndex!==null)return;manualPlaying=!manualPlaying;$('playBtn').textContent=manualPlaying?'PAUSE REPLAY':'START REPLAY'};$('resetBtn').onclick=()=>{index=Math.min(20,data.length-1);manualPlaying=false;pendingIndex=null;manualCredit=0;$('playBtn').textContent='START REPLAY';render();refreshExecutionPanel()};$('approveBtn').onclick=()=>{if(pendingIndex===null)return;index=pendingIndex;pendingIndex=null;render();refreshExecutionPanel();manualPlaying=true;$('playBtn').textContent='PAUSE REPLAY'};document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{setScenario(b.dataset.scenario);manualPlaying=false;pendingIndex=null;manualCredit=0;$('playBtn').textContent='START REPLAY';refreshExecutionPanel()});function controlledTick(t){if(manualPlaying){if(!manualLast)manualLast=t;manualCredit+=(t-manualLast)*Number($('speed').value)/1000;const steps=Math.floor(manualCredit);if(steps){manualCredit-=steps;advanceReplay(steps)}manualLast=t}else{manualLast=t}requestAnimationFrame(controlledTick)}setExecutionMode('auto');refreshExecutionPanel();requestAnimationFrame(controlledTick);
</script>"""


def build_scenarios(results, ledger_entries):
    scenarios = {}
    for name, (start, end) in HISTORICAL_REGIMES.items():
        event_start = int(results.index[results["date"] >= start][0])
        event_end = int(results.index[results["date"] >= end][0])
        beginning = max(0, event_start - 120)
        ending = min(len(results) - 1, event_end + 120)
        window = results.iloc[beginning : ending + 1]
        scenarios[name] = {
            "event_start": event_start - beginning,
            "event_end": event_end - beginning,
            "points": [
                {
                    "date": row.date.strftime("%Y-%m-%d"),
                    "hedged": round(float(row.strategy_value), 2),
                    "unhedged": round(float(row.buyhold_value), 2),
                    "risk": round(float(row.crash_probability), 4),
                    "equity": round(float(row.allocation_equity_pct), 4),
                    "gold": round(float(row.allocation_gold_pct), 4),
                    "cash": round(float(row.allocation_cash_pct), 4),
                    "action": row.action_taken,
                    "mode": row.mode,
                    "hash": ledger_entries[int(row.Index)]["hash"][:12],
                }
                for row in window.itertuples()
            ],
        }
    return scenarios


def main() -> None:
    prices = load_price_data(str(ROOT / "data" / "prices.csv"))
    model = load_model(str(ROOT / "models" / "crash_classifier.pkl"))
    ledger = HashChainLedger()
    results = run_backtest(prices, compute_features(prices), model, SimulatedBroker(), ledger)
    payload = json.dumps(build_scenarios(results, ledger.entries), separators=(",", ":"))
    html = TEMPLATE.replace("__SCENARIOS__", payload).replace(
        "function phase(){return index<eventStart?'normal':index<=eventEnd?'crash':'recovery'}",
        "function phase(){const r=data[index],hasDefended=data.slice(0,index+1).some(x=>x.action.indexOf('SELL EQUITY')===0);return r.mode==='defensive'?'crash':hasDefended?'recovery':'normal'}",
    )
    html = html.replace("</style>", UX_CSS + "</style>")
    html = html.replace("</div>\n<div class=\"phasebar\">", "</div>\n" + EXECUTION_PANEL + "\n<div class=\"phasebar\">")
    html = html.replace("</section><div class=\"note\">", "</section>" + LEDGER_PANEL + "<div class=\"note\">")
    html = html.replace("allocations()}", "allocations();if(typeof renderLedger==='function'){renderLedger()}}")
    html = html.replace("</body></html>", LEDGER_SCRIPT + MANUAL_MODE_SCRIPT + "</body></html>")
    if "id=\"manualMode\"" not in html or "id=\"ledgerRows\"" not in html:
        raise RuntimeError("Execution-mode controls or ledger panel were not added to the demo HTML.")
    OUTPUT.write_text(html, encoding="utf-8")
    print(f"Built standalone demo: {OUTPUT}")


